 "content": "def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        # Extend a row's rightmost colored segment through the remaining
        # background, highlighting that trailing continuation with color 1.
        nonbg = [c for c, v in enumerate(row) if v != bg]
        if nonbg:
            last = nonbg[-1]
            if last < len(row) - 1:
                for c in range(last + 1, len(row)):
                    out[r][c] = 1
    return out

